#include <gnuradio/uwb/uwb_demod_core.h>
#include <gnuradio/uwb/uwb_rational_resampler_core.h>
#include <fstream>
#include <iostream>
#include <iomanip>
using namespace gr::uwb;
template<class T> std::vector<T> load(const char* p){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error(p);auto n=f.tellg();std::vector<T> v(size_t(n)/sizeof(T));f.seekg(0);f.read((char*)v.data(),n);return v;}
int main(int argc,char** argv){if(argc<5)return 2;auto taps=load<float>("testdata/resampler_65_48/taps_quality_minorder.txt");auto tmpl=load<std::complex<float>>("testdata/reference_preamble_code10_998p4.cf32");core::RationalResampler65_48Core rs(taps);rs.set_fixed_phase_schedule(true);std::ifstream f(argv[1],std::ios::binary),starts(argv[2]);demod::Qm35825Profile p;p.code_index=10;p.preamble_repetitions=256;p.cir_repetitions=246;p.sfd_mode=argv[3];if(argc>5){p.preamble_repetitions=std::stoi(argv[5]);p.cir_repetitions=p.preamble_repetitions-10;}if(argc>7)p.cfo_skip_initial_repetitions=p.preamble_repetitions-40;if(argc>8){p.rx_fused_payload_cmf=true;p.rx_fused_phr_cmf=true;}if(argc>6){p.rx_fast_sfd=true;p.rx_fast_cfo_rotation=true;p.rx_seed_refine_tail=true;p.rx_softchip_on_demand=true;}p.cir_soft_chip_mode=std::stoi(argv[4])?demod::CirSoftChipMode::Bypass:demod::CirSoftChipMode::Full;demod::core::DemodScratch scratch;int64_t seed;int k=0;while(starts>>seed){int64_t a=seed-14746;size_t n=390000;if(a<0)continue;std::vector<std::complex<int16_t>> x(n);f.clear();f.seekg(a*4);f.read((char*)x.data(),n*4);if(f.gcount()!=int64_t(n*4))continue;rs.reset();std::vector<std::complex<float>> y(rs.expected_output_length(n));auto z=rs.process_sc16(x.data(),n,1.f/32768,y.data(),y.size());size_t made=z.produced;while(made<y.size()){auto c=rs.flush(y.data()+made,y.size()-made);if(!c)break;made+=c;}if(k==0){std::ofstream dump("testdata/x410_fixed_tone_live_20261115/first_window.cf32",std::ios::binary);dump.write((char*)y.data(),made*8);}auto r=demod::core::demodulate_one(y.data(),made,p,k++,llround((seed-a)*65./48),0,tmpl,scratch);std::cout<<"{\"id\":"<<k-1<<",\"seed\":"<<seed<<",\"status\":"<<int(r.status)<<",\"timing_ok\":"<<r.timing.ok<<",\"timing_metric\":"<<r.timing.metric<<",\"detected\":"<<r.timing.preamble_start_sample<<",\"peaks\":"<<r.timing.detected_peaks<<",\"cfo\":"<<r.cfo.cfo_hz<<",\"sfd_ok\":"<<r.sfd.ok<<",\"phr_ok\":"<<r.phr.ok<<",\"length\":"<<r.phr.psdu_length<<",\"fcs\":"<<r.payload.fcs_pass<<",\"us\":"<<r.stage_total_us<<",\"hex\":\"";for(auto b:r.payload.bytes)std::cout<<std::hex<<std::setw(2)<<std::setfill('0')<<int(b);std::cout<<std::dec<<"\"}\n";}}
